import type {ImageDefinition, ImageVersion} from '../types/types'
import {CustomImageHeaderDescription} from './CustomImageHeaderDescription'
import {CustomImageVersionsTable} from './CustomImageVersionsTable'

interface CustomImageDetailsViewProps {
  imageDefinition: ImageDefinition
  imageVersions: ImageVersion[]
}

export function CustomImageDetailsView(props: CustomImageDetailsViewProps) {
  const customImageVersionsCount = props.imageVersions.length

  return (
    <>
      <CustomImageHeaderDescription customImage={props.imageDefinition} />
      {customImageVersionsCount > 0 && (
        <CustomImageVersionsTable customImage={props.imageDefinition} customImageVersions={props.imageVersions} />
      )}
    </>
  )
}

try{ CustomImageDetailsView.displayName ||= 'CustomImageDetailsView' } catch {}