import {useEffect} from 'react'
import {Button, Label, Text} from '@primer/react'
import {DataTable, Table} from '@primer/react/experimental'
import type {ImageDefinition, ImageVersion} from '../types/types'
import {formatDateString} from '../helpers/utils'

interface CustomImageVersionsTableProps {
  customImage: ImageDefinition
  customImageVersions: ImageVersion[]
}

export function CustomImageVersionsTable(props: CustomImageVersionsTableProps) {
  // id generated for DataTable
  const customImageVersionsWithIds = props.customImageVersions.map(version => ({
    ...version,
    id: `${version.imageDefinitionId}-${version.version}`,
  }))

  useEffect(() => {
    window.scrollTo(0, 0)
  }, [])

  return (
    <div>
      <Table.Container>
        <Table.Title as="h2" id="customer-images">
          Image Versions ({customImageVersionsWithIds.length})
        </Table.Title>
        <Table.Actions>
          {props.customImage.latestVersion && (
            <Button variant="default" size="small" disabled>
              Latest version: <strong>{props.customImage.latestVersion}</strong>
            </Button>
          )}
        </Table.Actions>
        <DataTable
          data={customImageVersionsWithIds}
          columns={[
            {
              header: 'Version',
              field: 'version',
              renderCell: row => {
                return (
                  <Text as="span" weight="normal">
                    {row.version} {row.version === props.customImage.latestVersion && <Label>Latest</Label>}
                  </Text>
                )
              },
            },
            {
              header: 'State',
              field: 'state',
            },
            {
              header: 'SizeGB',
              field: 'sizeGb',
            },
            {
              header: 'Created At',
              field: 'createdAt',
              renderCell: row => {
                return (
                  <Text as="span" weight="normal">
                    {formatDateString(new Date(row.createdAt))}
                  </Text>
                )
              },
            },
          ]}
        />
      </Table.Container>
    </div>
  )
}

try{ CustomImageVersionsTable.displayName ||= 'CustomImageVersionsTable' } catch {}